<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingLiveRefresh} from './workspaceRealtime';
import {ref,watch,computed} from 'vue';
import {useAccountingPermissions} from './permissions';
const can=useAccountingPermissions(),props=defineProps<{company:number;book:any}>(),emit=defineEmits(['navigate','cheques']);
const data=ref<any>({}),cheques=ref<any>(null),loading=ref(false),error=ref('');let generation=0;
const today=new Date().toLocaleDateString('en-CA'),from=ref(today.slice(0,7)+'-01'),to=ref(today);
const amount=(v:any)=>Number(v||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
const cash=computed(()=>data.value.cashflow),showMovements=ref(false);
const activityNames:Record<string,string>={operating:'Operating activities',investing:'Investing activities',financing:'Financing activities',review:'Needs classification review'};
const cards=computed(()=>[
 {name:'Cash & bank balance',value:cash.value?.summary.closing,permission:'reports.cashflow',target:'ledger',hint:'At selected end date',icon:'cash'},
 {name:'Accounts receivable',value:data.value.receivables?.summary.outstanding,permission:'reports.receivables',target:'receivables',hint:'Posted receipts / credits: '+amount(data.value.receivables?.summary.ledger_credit),icon:'in'},
 {name:'Accounts payable',value:data.value.payables?.summary.outstanding,permission:'reports.payables',target:'payables',hint:'Posted payments / debits: '+amount(data.value.payables?.summary.ledger_debit),icon:'out'},
 {name:'Income for period',value:data.value.profit?.summary.income,permission:'reports.profit',target:'profit',hint:'Posted income · accrual basis',icon:'chart'},
 {name:'Expenses for period',value:data.value.profit?.summary.expense,permission:'reports.profit',target:'profit',hint:'Posted expenses · accrual basis',icon:'chart'},
].filter(c=>can(c.permission)));
async function load(){const token=++generation;data.value={};cheques.value=null;error.value='';if(!props.book)return;loading.value=true;const company=props.company,period={from:from.value,to:to.value};
try{
 const requests=['cashflow','profit','receivables','payables'].filter(r=>can('reports.'+r)).map(async report=>{const params=new URLSearchParams({company_id:String(company),report,from:period.from,to:period.to});const r=await fetch('/accounting/api/reports?'+params,{headers:{Accept:'application/json'}});const result=await r.json();if(!r.ok)throw Error(result.message||'Unable to load financial overview.');return [report,result];});
 if(can('cheques.view'))requests.push((async()=>{const r=await fetch('/accounting/api/cheques?'+new URLSearchParams({company_id:String(company),from:period.from,to:period.to}),{headers:{Accept:'application/json'}});const result=await r.json();if(!r.ok)throw Error(result.message||'Unable to load cheque totals.');return ['cheques',result.summary];})());
 const results=Object.fromEntries(await Promise.all(requests));if(token!==generation)return;data.value={...results,period};cheques.value=results.cheques;
}catch(e){if(token===generation)error.value=(e as Error).message;}finally{if(token===generation)loading.value=false;}}
watch(()=>[props.company,props.book],()=>void load(),{immediate:true});
const csv=computed(()=>'/accounting/api/reports?'+new URLSearchParams({company_id:String(props.company),report:'cashflow',from:cash.value?.from||from.value,to:cash.value?.to||to.value,export:'csv'}));
function currentMonth(){from.value=today.slice(0,7)+'-01';to.value=today;void load();}
useAccountingLiveRefresh(()=>load(),()=>true);
useAccountingAlerts(error);
</script>
<template><section class="ac-financial-dashboard"><div class="ac-section-heading"><div><p class="eyebrow">FINANCIAL WORKSPACE</p><h2>Financial overview</h2><p class="muted">Cash position, outstanding invoices and cheque activity in one place.</p></div><span class="ac-badge active">{{book?.currency||'Books not configured'}}</span></div>
<form v-if="book" class="ac-dashboard-period" @submit.prevent="load"><div><strong>Reporting period</strong><small>Cash movements and accrual totals follow these dates.</small></div><label>From<input v-model="from" type="date" required :max="to"></label><label>To<input v-model="to" type="date" required :min="from" :max="today"></label><button class="button primary" :disabled="loading">{{loading?'Updating...':'Update overview'}}</button><button type="button" class="button" :disabled="loading" @click="currentMonth">This month</button></form>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="loading" class="ac-help" role="status">Loading posted financial balances...</p>
<div v-else-if="!book" class="ac-empty"><h3>Set up your company books</h3><p>Configure your books before recording financial transactions.</p><button class="button primary" @click="emit('navigate','books')">Open Company books</button></div>
<template v-else-if="!error"><div class="ac-dashboard-kpis"><button v-for="card in cards" :key="card.name" @click="emit('navigate',card.target)"><span class="ac-dashboard-kpi-top"><small>{{card.name}}</small><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 5h18v14H3z M3 9h18 M7 14h4 M17 14h1"/></svg></span><strong>{{amount(card.value)}}</strong><small>{{card.hint}}</small></button></div>
<div v-if="cash" class="ac-dashboard-grid"><article class="ac-dashboard-statement"><header><div><p class="eyebrow">POSTED CASH MOVEMENTS</p><h3>Cash flow statement</h3><small>{{cash.from}} — {{cash.to}} · {{cash.currency}}</small></div><a v-if="can('reports.export')" class="button" :href="csv">Download CSV</a></header>
<div class="ac-cash-opening"><span>Opening cash & bank balance</span><strong>{{amount(cash.summary.opening)}}</strong></div>
<div class="ac-cash-totals"><div><small>Combined inflows</small><strong class="ac-cash-in">+{{amount(cash.summary.inflow)}}</strong></div><div><small>Combined outflows</small><strong class="ac-cash-out">-{{amount(cash.summary.outflow)}}</strong></div></div>
<div class="ac-cash-totals"><div><small>Cash inflow</small><strong class="ac-cash-in">+{{amount(cash.summary.cash_inflow)}}</strong></div><div><small>Cash outflow</small><strong class="ac-cash-out">-{{amount(cash.summary.cash_outflow)}}</strong></div><div><small>Bank inflow</small><strong class="ac-cash-in">+{{amount(cash.summary.bank_inflow)}}</strong></div><div><small>Bank outflow</small><strong class="ac-cash-out">-{{amount(cash.summary.bank_outflow)}}</strong></div></div><p class="ac-help">Cash and bank breakdowns include internal transfers. Combined inflows and outflows exclude internal transfers; opening entries are shown separately.</p>
<dl class="ac-cash-activities"><div v-for="(name,key) in activityNames" :key="key"><dt>{{name}}</dt><dd>{{amount(cash.activities[key])}}</dd></div></dl>
<div v-if="Number(cash.summary.opening_adjustments)" class="ac-cash-opening"><span>Opening balance entries in period</span><strong>{{amount(cash.summary.opening_adjustments)}}</strong></div><div class="ac-cash-opening"><span>Net cash movement</span><strong>{{amount(cash.summary.net)}}</strong></div><div class="ac-cash-closing"><span>Closing cash & bank balance</span><strong>{{amount(cash.summary.closing)}}</strong></div>
<p v-if="cash.review_count" class="ac-help" role="status">{{cash.review_count}} cash movement(s) need classification review. Their amounts remain included in the reconciled cash totals; activity classifications are provisional.</p>
<footer><small>Posted Cash/Bank accounts only, including officer cash funds. Drafts and pending cheques are excluded. Transfers within Cash/Bank are excluded from cash flow totals.</small><button type="button" class="button" :aria-expanded="showMovements" @click="showMovements=!showMovements">{{showMovements?'Hide movements':'View movements'}}</button></footer>
</article><article class="ac-dashboard-bank"><header><p class="eyebrow">LIQUIDITY</p><h3>Cash & bank accounts</h3><small>Balances at {{cash.to}}</small></header><div class="ac-bank-balances"><div v-for="a in cash.accounts" :key="a.id"><span><strong>{{a.name}}</strong><small>{{a.code}} · {{a.type}}</small></span><strong>{{amount(a.balance)}}</strong></div><p v-if="!cash.accounts.length" class="muted">No posted cash or bank balances yet.</p></div><button v-if="can('reports.ledger')" class="button" @click="emit('navigate','ledger')">Open General Ledger <svg class="ac-shortcut-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button></article></div>
<div v-if="cash&&showMovements" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Date</th><th>Journal / description</th><th>Activity</th><th class="numeric">Cash in</th><th class="numeric">Cash out</th></tr></thead><tbody><tr v-for="r in cash.rows" :key="r.id"><td>{{r.date}}</td><td><strong>{{r.number}}</strong><small>{{r.description}}</small></td><td>{{activityNames[r.category]}}</td><td class="numeric">{{amount(r.inflow)}}</td><td class="numeric">{{amount(r.outflow)}}</td></tr><tr v-if="!cash.rows.length"><td colspan="5" class="ac-empty-small">No cash movements in this period.</td></tr></tbody></table></div>
<section v-if="cheques" class="ac-dashboard-pdc"><div class="ac-section-heading"><div><h3>Post-dated cheques</h3><p class="muted">Issued/received: outstanding at {{data.period?.to||to}}. Cleared/bounced: {{data.period?.from||from}} to {{data.period?.to||to}}.</p></div></div><div class="ac-stats ac-overview-stats"><button v-for="key in ['issued','received','bounced','cleared']" :key="key" @click="emit('cheques',key,{from:data.period?.from||from,to:data.period?.to||to})"><small>PDC {{key}}</small><small>{{['issued','received'].includes(key)?'Outstanding at '+(data.period?.to||to):(data.period?.from||from)+' to '+(data.period?.to||to)}}</small><strong>{{cheques[key].count}}</strong><span>{{book.currency}} {{amount(cheques[key].amount)}}</span></button></div></section>
<article class="ac-books-panel ac-dashboard-shortcuts"><h3>Quick actions</h3><div class="ac-quick-actions"><button class="button" v-if="can('sales.view')" @click="emit('navigate','sales')">Sales invoices <svg class="ac-shortcut-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button><button class="button" v-if="can('purchases.view')" @click="emit('navigate','purchases')">Purchase invoices <svg class="ac-shortcut-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button><button class="button" v-if="can('journals.view')" @click="emit('navigate','journals')">Journal entries <svg class="ac-shortcut-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button><button class="button" v-if="can('reports.trial')" @click="emit('navigate','trial')">Trial Balance <svg class="ac-shortcut-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button></div></article>
</template></section></template>
<style>
.ac-dashboard-period{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--rail);margin-bottom:22px}.ac-dashboard-period>div{margin-right:auto}.ac-dashboard-period strong{font-size:13px}.ac-dashboard-period small{display:block;font-size:11px;color:var(--muted);margin-top:6px}.ac-dashboard-period label{font-size:11px;min-width:140px}.ac-dashboard-period input{margin-top:6px}.ac-dashboard-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin-bottom:24px}.ac-dashboard-kpis>button{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--rail);padding:18px;text-align:left;color:var(--text);cursor:pointer}.ac-dashboard-kpis>button:first-child{border-top:3px solid var(--ac-accent)}.ac-dashboard-kpi-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.ac-dashboard-kpi-top svg{width:20px;height:20px;color:var(--ac-accent);flex:none}.ac-dashboard-kpis small{font-size:11px;color:var(--muted)}.ac-dashboard-kpis>button>strong{display:block;font-size:24px;margin:16px 0 10px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.ac-dashboard-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,1fr);gap:20px;margin-bottom:24px}.ac-dashboard-statement,.ac-dashboard-bank{border:1px solid var(--line);border-radius:14px;background:var(--rail);padding:24px;min-width:0}.ac-dashboard-statement header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:24px}.ac-financial-dashboard h3{font-size:18px;margin:6px 0 10px}.ac-dashboard-grid small{font-size:11px;color:var(--muted)}.ac-cash-opening,.ac-cash-closing{display:flex;justify-content:space-between;gap:14px;padding:15px 0;font-size:13px}.ac-cash-closing{border-top:3px double var(--line);font-size:16px;margin-top:6px}.ac-cash-closing strong{color:var(--ac-accent)}.ac-cash-totals{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0 20px}.ac-cash-totals>div{padding:16px;border:1px solid var(--line);border-radius:10px;background:var(--bg)}.ac-cash-totals strong{display:block;margin-top:9px;font-size:21px;font-variant-numeric:tabular-nums}.ac-cash-in{color:#168461}.ac-cash-out{color:#d05d52}.ac-cash-activities{margin:0;border-bottom:1px solid var(--line)}.ac-cash-activities>div{display:flex;justify-content:space-between;gap:16px;padding:11px 0;font-size:12px}.ac-cash-activities dt{color:var(--muted)}.ac-cash-activities dd{margin:0;font-variant-numeric:tabular-nums}.ac-dashboard-statement footer{border-top:1px solid var(--line);padding-top:16px;margin-top:12px;display:flex;align-items:center;gap:14px}.ac-dashboard-statement footer small{line-height:1.6;flex:1}.ac-bank-balances{max-height:350px;overflow-y:auto;margin:20px 0}.ac-bank-balances>div{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 0;border-bottom:1px solid var(--line);font-size:13px}.ac-bank-balances span small{display:block;margin-top:6px}.ac-bank-balances span{min-width:0;overflow-wrap:anywhere}.ac-bank-balances>div>strong{white-space:nowrap;font-size:12px}.ac-dashboard-pdc{margin-top:30px}.ac-financial-dashboard .ac-dashboard-shortcuts{margin-top:24px;max-width:none;width:100%;box-sizing:border-box;min-width:0}.ac-dashboard-shortcuts .ac-quick-actions>.button{justify-self:stretch;display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0}.ac-shortcut-arrow{width:17px;height:17px;flex:none}.ac-dashboard-shortcuts .ac-quick-actions{grid-template-columns:repeat(4,minmax(0,1fr))}.ac-financial-dashboard .ac-table-wrap{max-height:420px;overflow:auto}@media(max-width:1100px){.ac-dashboard-grid{grid-template-columns:minmax(0,1fr)}.ac-dashboard-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.ac-dashboard-period>div{width:100%}.ac-dashboard-period label{flex:1;min-width:100px}.ac-dashboard-statement,.ac-dashboard-bank{padding:16px}.ac-dashboard-statement header,.ac-dashboard-statement footer{align-items:flex-start;flex-direction:column}.ac-dashboard-kpis>button>strong{font-size:20px}.ac-dashboard-shortcuts .ac-quick-actions{grid-template-columns:1fr 1fr}.ac-cash-totals strong{font-size:18px}}
</style>
